        imported_items = match.group(1).strip()
        for item in imported_items.split(','):
            item = item.strip()
            if item and not item.startswith('('):
                imported[filepath].add(item)

    # Find multi-line imports
    for match in re.finditer(r'from src\.constants import\s*\(\s*\n([^)]+)\)', content, re.DOTALL):
